-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/024_align_recurring_water_price.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroTap: align recurring Normal RO with approved launch price.
-- Forward-only, idempotent. Does not rewrite historical orders or tax fields.
-- Active subscriptions using the previous ₹18 rate are aligned for future deliveries.
BEGIN;

UPDATE public.settings
SET value = '20', updated_at = now()
WHERE key = 'subscription_can_price'
  AND value IS DISTINCT FROM '20';

INSERT INTO public.settings (key, value)
VALUES ('subscription_can_price', '20')
ON CONFLICT (key) DO NOTHING;

DO $$
BEGIN
  IF to_regclass('public.water_subscriptions') IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'water_subscriptions'
         AND column_name = 'price_per_can'
     )
     AND EXISTS (
       SELECT 1
       FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = 'water_subscriptions'
         AND column_name = 'status'
     )
  THEN
    EXECUTE $update$
      UPDATE public.water_subscriptions
      SET price_per_can = 20
      WHERE status = 'ACTIVE'
        AND price_per_can = 18
    $update$;
  END IF;
END
$$;

SELECT pg_notify('pgrst', 'reload schema');

COMMIT;


-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/025_dispatch_alert_idempotency.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroTap: prevent retry loops from flooding notifications and audit_logs.
-- Additive and idempotent. Existing historical audit records are preserved.
BEGIN;

CREATE TABLE IF NOT EXISTS public.dispatch_alert_events (
  order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  action text NOT NULL CHECK (
    action IN (
      'no_supplier',
      'dispatch_exhausted',
      'technician_no_candidates',
      'technician_dispatch_exhausted'
    )
  ),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (order_id, action)
);

ALTER TABLE public.dispatch_alert_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.dispatch_alert_events FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.dispatch_alert_events TO service_role;

-- Seed the dedup table for already-completed orders so the next cron run does
-- not generate another alert for historical failures that were later completed.
INSERT INTO public.dispatch_alert_events (order_id, action)
SELECT DISTINCT
  o.id,
  replace(a.action, 'order.', '')
FROM public.orders AS o
JOIN public.audit_logs AS a
  ON a.entity_id::text IN (o.id::text, o.order_number)
WHERE o.status = 'COMPLETED'
  AND a.action IN (
    'order.no_supplier',
    'order.dispatch_exhausted',
    'order.technician_no_candidates',
    'order.technician_dispatch_exhausted'
  )
ON CONFLICT (order_id, action) DO NOTHING;

COMMIT;


-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/026_supplier_finance_integrity.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroTap supplier finance integrity: additive, forward-only migration.
-- Does not rewrite historical orders, payouts, or ledger entries.
BEGIN;

ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS payment_collector TEXT,
  ADD COLUMN IF NOT EXISTS payment_collected_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS payment_collected_amount NUMERIC(10,2),
  ADD COLUMN IF NOT EXISTS payment_collected_at TIMESTAMPTZ;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.orders'::regclass
      AND conname = 'orders_payment_collector_check'
  ) THEN
    ALTER TABLE public.orders
      ADD CONSTRAINT orders_payment_collector_check
      CHECK (payment_collector IS NULL OR payment_collector IN ('supplier', 'aurotap')) NOT VALID;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.orders'::regclass
      AND conname = 'orders_payment_collected_amount_nonnegative'
  ) THEN
    ALTER TABLE public.orders
      ADD CONSTRAINT orders_payment_collected_amount_nonnegative
      CHECK (payment_collected_amount IS NULL OR payment_collected_amount >= 0) NOT VALID;
  END IF;
END
$$;

-- Supplier earnings are the supplier's entitlement, not customer gross sales.
-- Restrict direct RPC calls so a supplier cannot query another supplier's totals.
CREATE OR REPLACE FUNCTION public.get_supplier_earnings(p_supplier_id UUID, p_period TEXT)
RETURNS TABLE (period_label TEXT, order_count BIGINT, gross_amount NUMERIC, pending_payout NUMERIC)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  start_ts TIMESTAMPTZ;
  pl TEXT;
  caller_role TEXT;
BEGIN
  SELECT p.role INTO caller_role FROM public.profiles p WHERE p.id = auth.uid();
  IF auth.uid() IS DISTINCT FROM p_supplier_id AND caller_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'forbidden_supplier_earnings' USING ERRCODE = '42501';
  END IF;

  pl := lower(coalesce(p_period, 'month'));
  IF pl NOT IN ('today', 'week', 'month') THEN pl := 'month'; END IF;
  start_ts := CASE pl
    WHEN 'today' THEN date_trunc('day', NOW())
    WHEN 'week' THEN date_trunc('week', NOW())
    ELSE date_trunc('month', NOW())
  END;

  RETURN QUERY
  SELECT pl::TEXT, COUNT(*)::BIGINT,
    COALESCE(SUM(o.supplier_payout) FILTER (WHERE COALESCE(o.supplier_payout, 0) > 0), 0)::NUMERIC,
    COALESCE(SUM(o.supplier_payout) FILTER (
      WHERE COALESCE(o.supplier_payout, 0) > 0
        AND lower(COALESCE(o.payout_status, 'pending')) = 'pending'
    ), 0)::NUMERIC
  FROM public.orders o
  WHERE o.supplier_id = p_supplier_id
    AND upper(COALESCE(o.status, '')) = 'COMPLETED'
    AND COALESCE(o.completed_at, o.created_at) >= start_ts;
END;
$$;

-- Complete a supplier order and post its verified entitlement in the same transaction.
-- Only the confirmed single-can ₹20 order rule is credited automatically. Other amounts
-- remain unposted until the supplier payout schedule is approved.
CREATE OR REPLACE FUNCTION public.complete_supplier_order_atomic(
  p_order_id UUID,
  p_supplier_id UUID,
  p_payment_confirmed BOOLEAN,
  p_payment_reference TEXT,
  p_payment_collector TEXT
)
RETURNS SETOF public.orders
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role TEXT;
  v_order public.orders%ROWTYPE;
  v_now TIMESTAMPTZ := NOW();
  v_was_paid BOOLEAN;
  v_method TEXT;
  v_supplier_entitlement NUMERIC(10,2);
BEGIN
  IF auth.uid() IS DISTINCT FROM p_supplier_id THEN
    RAISE EXCEPTION 'supplier_identity_mismatch' USING ERRCODE = '42501';
  END IF;
  SELECT p.role INTO v_role FROM public.profiles p WHERE p.id = auth.uid();
  IF v_role IS DISTINCT FROM 'supplier' THEN
    RAISE EXCEPTION 'supplier_role_required' USING ERRCODE = '42501';
  END IF;

  SELECT o.* INTO v_order
  FROM public.orders o
  WHERE o.id = p_order_id AND o.supplier_id = p_supplier_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found_or_forbidden' USING ERRCODE = '42501'; END IF;
  IF upper(COALESCE(v_order.status, '')) <> 'IN_PROGRESS' THEN
    RAISE EXCEPTION 'invalid_order_transition' USING ERRCODE = '40001';
  END IF;

  v_was_paid := lower(COALESCE(v_order.payment_status, 'unpaid')) = 'paid';
  v_method := lower(COALESCE(v_order.payment_method, 'cash'));

  IF NOT v_was_paid AND p_payment_confirmed IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'payment_confirmation_required' USING ERRCODE = '22023';
  END IF;
  IF NOT v_was_paid AND v_method = 'upi' AND NULLIF(btrim(COALESCE(p_payment_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'upi_reference_required' USING ERRCODE = '22023';
  END IF;
  IF NOT v_was_paid AND (
    p_payment_collector IS NULL OR p_payment_collector NOT IN ('supplier', 'aurotap')
  ) THEN
    RAISE EXCEPTION 'payment_collector_required' USING ERRCODE = '22023';
  END IF;

  -- The approved single-can launch case is ₹20 customer total -> ₹20 supplier entitlement.
  -- Never infer multi-can or non-standard supplier rates from the customer total.
  v_supplier_entitlement := NULL;
  IF lower(COALESCE(v_order.service_type, '')) = 'water_can'
     AND COALESCE(v_order.can_count, 0) = 1
     AND COALESCE(v_order.total_amount, 0) = 20 THEN
    v_supplier_entitlement := 20;
  END IF;

  UPDATE public.orders
  SET status = 'COMPLETED',
      completed_at = v_now,
      payment_status = CASE WHEN v_was_paid THEN payment_status ELSE 'paid' END,
      payment_confirmed_at = CASE WHEN v_was_paid THEN payment_confirmed_at ELSE v_now END,
      payment_reference = CASE WHEN v_was_paid THEN payment_reference ELSE NULLIF(btrim(COALESCE(p_payment_reference, '')), '') END,
      payment_collector = CASE WHEN v_was_paid THEN payment_collector ELSE p_payment_collector END,
      payment_collected_by = CASE WHEN v_was_paid THEN payment_collected_by WHEN p_payment_collector = 'supplier' THEN p_supplier_id ELSE NULL END,
      payment_collected_amount = CASE WHEN v_was_paid THEN payment_collected_amount ELSE total_amount END,
      payment_collected_at = CASE WHEN v_was_paid THEN payment_collected_at ELSE v_now END,
      supplier_payout = CASE
        WHEN v_supplier_entitlement IS NOT NULL
          AND financials_posted_at IS NULL
          AND COALESCE(supplier_payout, 0) <> v_supplier_entitlement
        THEN v_supplier_entitlement
        ELSE supplier_payout
      END,
      payout_status = CASE
        WHEN v_supplier_entitlement IS NOT NULL
          AND financials_posted_at IS NULL
          AND COALESCE(supplier_payout, 0) <> v_supplier_entitlement
        THEN 'pending'
        ELSE payout_status
      END
  WHERE id = p_order_id AND supplier_id = p_supplier_id
  RETURNING * INTO v_order;

  IF v_supplier_entitlement IS NOT NULL AND v_order.financials_posted_at IS NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.wallet_ledger wl
      WHERE wl.order_id = p_order_id AND wl.entry_type = 'ORDER_EARNING'
    ) THEN
      INSERT INTO public.wallet_ledger (
        payee_id, payee_role, order_id, entry_type, amount, note, metadata, created_by
      )
      VALUES (
        p_supplier_id, 'supplier', p_order_id, 'ORDER_EARNING', v_supplier_entitlement,
        'Supplier entitlement for verified ₹20 single-can water order',
        jsonb_build_object('service_type', 'water_can', 'can_count', 1, 'customer_total', v_order.total_amount),
        p_supplier_id
      );
    ELSE
      RAISE EXCEPTION 'order_earning_ledger_already_exists' USING ERRCODE = '23505';
    END IF;

    UPDATE public.orders
    SET financials_posted_at = v_now, financials_payee_id = p_supplier_id
    WHERE id = p_order_id AND supplier_id = p_supplier_id
    RETURNING * INTO v_order;
  END IF;

  RETURN NEXT v_order;
END;
$$;

REVOKE ALL ON FUNCTION public.complete_supplier_order_atomic(UUID, UUID, BOOLEAN, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_supplier_order_atomic(UUID, UUID, BOOLEAN, TEXT, TEXT) TO authenticated;

-- Atomic payout request creation; advisory lock serializes concurrent requests per supplier.
CREATE OR REPLACE FUNCTION public.request_supplier_payout(
  p_amount NUMERIC, p_method TEXT, p_details JSONB
)
RETURNS TABLE (id UUID, amount NUMERIC, method TEXT, status TEXT, paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_role TEXT;
  v_row public.payouts%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 1000000 THEN
    RAISE EXCEPTION 'invalid_payout_amount' USING ERRCODE = '22023';
  END IF;
  IF p_method NOT IN ('upi', 'bank') OR jsonb_typeof(COALESCE(p_details, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'invalid_payout_details' USING ERRCODE = '22023';
  END IF;
  IF p_method = 'upi' AND COALESCE(p_details->>'upi_id', '') !~* '^[a-z0-9._-]{2,256}@[a-z][a-z0-9]{1,63}$' THEN
    RAISE EXCEPTION 'invalid_upi_id' USING ERRCODE = '22023';
  END IF;
  IF p_method = 'bank' AND (
    COALESCE(p_details->>'bank_account', '') !~ '^[0-9]{9,18}$'
    OR COALESCE(p_details->>'ifsc', '') !~* '^[A-Z]{4}0[A-Z0-9]{6}$'
  ) THEN
    RAISE EXCEPTION 'invalid_bank_details' USING ERRCODE = '22023';
  END IF;

  SELECT p.role INTO v_role FROM public.profiles p WHERE p.id = v_user_id;
  IF v_role IS DISTINCT FROM 'supplier' THEN RAISE EXCEPTION 'supplier_role_required' USING ERRCODE = '42501'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_user_id::TEXT || ':supplier_payout', 0));

  -- A legacy payout marked paid without its immutable ledger debit must be reconciled
  -- before another request; otherwise the same earnings could be requested twice.
  IF EXISTS (
    SELECT 1 FROM public.payouts p
    WHERE p.user_id = v_user_id AND p.role = 'supplier'
      AND lower(COALESCE(p.status, 'pending')) = 'paid'
      AND NOT EXISTS (
        SELECT 1 FROM public.wallet_ledger wl
        WHERE wl.payout_id = p.id AND wl.entry_type = 'PAYOUT'
      )
  ) THEN
    RAISE EXCEPTION 'payout_settlement_requires_reconciliation' USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.payouts p
    WHERE p.user_id = v_user_id AND p.role = 'supplier'
      AND lower(COALESCE(p.status, 'pending')) IN ('pending', 'approved')
  ) THEN
    RAISE EXCEPTION 'payout_request_pending' USING ERRCODE = '23505';
  END IF;

  IF COALESCE(public.payee_balance(v_user_id), 0) < p_amount THEN
    RAISE EXCEPTION 'insufficient_verified_supplier_balance' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.payouts (user_id, role, amount, status, method, note, payout_details, paid_at)
  VALUES (v_user_id, 'supplier', p_amount, 'pending', p_method, 'Supplier payout request', p_details, NULL)
  RETURNING * INTO v_row;

  RETURN QUERY SELECT v_row.id, v_row.amount, v_row.method, v_row.status, v_row.paid_at, v_row.created_at;
END;
$$;

REVOKE ALL ON FUNCTION public.request_supplier_payout(NUMERIC, TEXT, JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.request_supplier_payout(NUMERIC, TEXT, JSONB) TO authenticated;

SELECT pg_notify('pgrst', 'reload schema');
COMMIT;


-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/027_versioned_pricing_rules.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroTap versioned pricing rules and immutable order snapshots.
-- Additive migration: does not rewrite existing orders, earnings, payouts, or live settings.
BEGIN;

CREATE TABLE IF NOT EXISTS public.pricing_versions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  version INTEGER NOT NULL UNIQUE CHECK (version > 0),
  effective_from TIMESTAMPTZ NOT NULL,
  reason TEXT NOT NULL CHECK (char_length(trim(reason)) BETWEEN 3 AND 500),
  config JSONB NOT NULL CHECK (jsonb_typeof(config) = 'object'),
  created_by UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pricing_versions_config_required CHECK (
    config ? 'water_normal'
    AND config ? 'water_chilled'
    AND config ? 'water_subscription'
    AND config ? 'services'
    AND config ? 'convenience_fee'
    AND config ? 'emergency_surcharge'
    AND config ? 'gst_rate'
  )
);

CREATE INDEX IF NOT EXISTS pricing_versions_effective_idx
  ON public.pricing_versions (effective_from DESC, version DESC);

ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS pricing_version INTEGER,
  ADD COLUMN IF NOT EXISTS pricing_snapshot JSONB;

ALTER TABLE public.water_subscriptions
  ADD COLUMN IF NOT EXISTS pricing_version INTEGER,
  ADD COLUMN IF NOT EXISTS pricing_snapshot JSONB;

COMMENT ON COLUMN public.orders.pricing_version IS
  'Pricing version used when this order was created; historical values must not be recalculated from current settings.';
COMMENT ON COLUMN public.orders.pricing_snapshot IS
  'Immutable server-calculated price components and policy snapshot for audit/reconciliation.';

ALTER TABLE public.pricing_versions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS pricing_versions_admin_read ON public.pricing_versions;
CREATE POLICY pricing_versions_admin_read ON public.pricing_versions
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid() AND p.role = 'admin' AND p.is_active = true AND COALESCE(p.status, 'active') = 'active'
  ));

DROP POLICY IF EXISTS pricing_versions_active_read ON public.pricing_versions;
CREATE POLICY pricing_versions_active_read ON public.pricing_versions
  FOR SELECT TO anon, authenticated
  USING (effective_from <= now());

DROP POLICY IF EXISTS pricing_versions_admin_insert ON public.pricing_versions;
CREATE POLICY pricing_versions_admin_insert ON public.pricing_versions
  FOR INSERT TO authenticated
  WITH CHECK (
    created_by = auth.uid()
    AND EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid() AND p.role = 'admin' AND p.is_active = true
    )
  );

CREATE OR REPLACE FUNCTION public.prevent_pricing_version_mutation()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Pricing versions are immutable; publish a new version instead.';
END;
$$;

DROP TRIGGER IF EXISTS pricing_versions_immutable ON public.pricing_versions;
CREATE TRIGGER pricing_versions_immutable
  BEFORE UPDATE OR DELETE ON public.pricing_versions
  FOR EACH ROW EXECUTE FUNCTION public.prevent_pricing_version_mutation();

-- Seed a baseline version only if this migration has not already seeded/published one.
-- Prices are read from existing settings when available; approved launch fallbacks remain ₹20/₹25.
DO $$
DECLARE
  v_config JSONB;
  v_services JSONB;
  v_next_version INTEGER;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.pricing_versions) THEN
    SELECT COALESCE(
      (SELECT value::jsonb FROM public.settings WHERE key = 'service_base_prices'),
      '{"water_tanker":299,"ro_service":349,"plumbing":149,"borewell":499,"motor_pump":299,"tank_cleaning":599}'::jsonb
    ) INTO v_services;

    v_config := jsonb_build_object(
      'water_normal', COALESCE((SELECT value::numeric FROM public.settings WHERE key = 'default_can_price'), 20),
      'water_chilled', COALESCE((SELECT value::numeric FROM public.settings WHERE key = 'chilled_can_price'), 25),
      'water_subscription', 20,
      'bulk_can_price', COALESCE((SELECT value::numeric FROM public.settings WHERE key = 'bulk_can_price'), 20),
      'bulk_threshold', COALESCE((SELECT value::integer FROM public.settings WHERE key = 'bulk_threshold'), 50),
      'services', v_services || jsonb_build_object('plumbing_mistri', 700),
      'convenience_fee', COALESCE((SELECT value::numeric FROM public.settings WHERE key = 'convenience_fee'), 10),
      'emergency_surcharge', COALESCE((SELECT value::numeric FROM public.settings WHERE key = 'emergency_surcharge'), 30),
      -- Keep the current order API behaviour until tax policy is confirmed.
      'gst_rate', 0
    );

    SELECT COALESCE(MAX(version), 0) + 1 INTO v_next_version FROM public.pricing_versions;
    INSERT INTO public.pricing_versions (version, effective_from, reason, config)
    VALUES (v_next_version, now(), 'Baseline imported from existing settings; no historical orders changed.', v_config);
  END IF;
END $$;


-- Prevent later order updates from changing the price version or price snapshot.
CREATE OR REPLACE FUNCTION public.prevent_order_pricing_snapshot_mutation()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.pricing_version IS DISTINCT FROM OLD.pricing_version
     OR NEW.pricing_snapshot IS DISTINCT FROM OLD.pricing_snapshot THEN
    RAISE EXCEPTION 'Order pricing snapshots are immutable; use an approved adjustment/credit workflow.';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS orders_pricing_snapshot_immutable ON public.orders;
CREATE TRIGGER orders_pricing_snapshot_immutable
  BEFORE UPDATE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.prevent_order_pricing_snapshot_mutation();

CREATE OR REPLACE FUNCTION public.prevent_subscription_pricing_snapshot_mutation()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.pricing_version IS DISTINCT FROM OLD.pricing_version
     OR NEW.pricing_snapshot IS DISTINCT FROM OLD.pricing_snapshot THEN
    RAISE EXCEPTION 'Subscription pricing snapshots are immutable; create a new subscription contract to change its rate.';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS water_subscriptions_pricing_immutable ON public.water_subscriptions;
CREATE TRIGGER water_subscriptions_pricing_immutable
  BEFORE UPDATE ON public.water_subscriptions
  FOR EACH ROW EXECUTE FUNCTION public.prevent_subscription_pricing_snapshot_mutation();

-- Atomic version allocation + audit logging. The database is the final authority.
CREATE OR REPLACE FUNCTION public.publish_pricing_version(
  p_effective_from TIMESTAMPTZ,
  p_reason TEXT,
  p_config JSONB
)
RETURNS public.pricing_versions
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  actor UUID := auth.uid();
  next_version INTEGER;
  service_key TEXT;
  service_value JSONB;
  published public.pricing_versions;
BEGIN
  IF actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = actor AND role = 'admin' AND is_active = true AND COALESCE(status, 'active') = 'active'
  ) THEN
    RAISE EXCEPTION 'Administrator access required' USING ERRCODE = '42501';
  END IF;
  IF p_effective_from IS NULL OR p_effective_from < now() - interval '60 seconds' THEN
    RAISE EXCEPTION 'Effective date must be now or in the future' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR char_length(trim(p_reason)) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'Reason must be 3 to 500 characters' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_config) <> 'object'
    OR NOT (p_config ? 'water_normal')
    OR NOT (p_config ? 'water_chilled')
    OR NOT (p_config ? 'water_subscription')
    OR NOT (p_config ? 'bulk_can_price')
    OR NOT (p_config ? 'bulk_threshold')
    OR NOT (p_config ? 'services')
    OR NOT (p_config ? 'convenience_fee')
    OR NOT (p_config ? 'emergency_surcharge')
    OR NOT (p_config ? 'gst_rate') THEN
    RAISE EXCEPTION 'Pricing configuration is incomplete' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_config->'services') <> 'object'
    OR (p_config->>'water_normal')::numeric < 20 OR (p_config->>'water_normal')::numeric > 500
    OR (p_config->>'water_chilled')::numeric < 20 OR (p_config->>'water_chilled')::numeric > 500
    OR (p_config->>'water_subscription')::numeric < 20 OR (p_config->>'water_subscription')::numeric > 500
    OR (p_config->>'bulk_can_price')::numeric < 20
    OR (p_config->>'bulk_can_price')::numeric > (p_config->>'water_normal')::numeric
    OR (p_config->>'bulk_threshold')::integer < 2 OR (p_config->>'bulk_threshold')::integer > 200
    OR (p_config->>'convenience_fee')::numeric < 0 OR (p_config->>'convenience_fee')::numeric > 500
    OR (p_config->>'emergency_surcharge')::numeric < 0 OR (p_config->>'emergency_surcharge')::numeric > 5000
    OR (p_config->>'gst_rate')::numeric < 0 OR (p_config->>'gst_rate')::numeric > 1 THEN
    RAISE EXCEPTION 'Pricing values are outside approved limits; water prices must respect the current ₹20 single-can supplier payout rule; multi-can payout schedules remain unapproved.' USING ERRCODE = '22023';
  END IF;

  FOR service_key, service_value IN
    SELECT key, value FROM jsonb_each(p_config->'services')
  LOOP
    IF service_key !~ '^[a-z][a-z0-9_]{1,49}$'
      OR jsonb_typeof(service_value) <> 'number'
      OR (service_value::text)::numeric < 1
      OR (service_value::text)::numeric > 100000 THEN
      RAISE EXCEPTION 'Invalid service base price for %', service_key USING ERRCODE = '22023';
    END IF;
  END LOOP;

  PERFORM pg_advisory_xact_lock(hashtext('public.pricing_versions.version'));
  SELECT COALESCE(MAX(version), 0) + 1 INTO next_version FROM public.pricing_versions;

  INSERT INTO public.pricing_versions(version, effective_from, reason, config, created_by)
  VALUES (next_version, p_effective_from, trim(p_reason), p_config, actor)
  RETURNING * INTO published;

  INSERT INTO public.audit_logs(actor_id, action, entity, entity_id, meta)
  VALUES (actor, 'pricing.version.publish', 'pricing_versions', NULL,
    jsonb_build_object('version', next_version, 'effective_from', p_effective_from,
      'reason', trim(p_reason), 'config', p_config));

  RETURN published;
END;
$$;

REVOKE ALL ON FUNCTION public.publish_pricing_version(TIMESTAMPTZ, TEXT, JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.publish_pricing_version(TIMESTAMPTZ, TEXT, JSONB) TO authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.pricing_versions FROM authenticated, anon;

COMMIT;

-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/028_referral_rewards.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroTap referral rewards v1.
-- Additive only: keeps profiles.referral_code/referred_by and referral_credits intact.
BEGIN;

CREATE TABLE IF NOT EXISTS public.referral_reward_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  referrer_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  referred_customer_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  qualifying_order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  address_id UUID REFERENCES public.addresses(id) ON DELETE SET NULL,
  address_fingerprint TEXT NOT NULL,
  reward_type TEXT NOT NULL CHECK (reward_type IN ('discount_25', 'free_water_can')),
  reward_status TEXT NOT NULL DEFAULT 'available'
    CHECK (reward_status IN ('available', 'reserved', 'redeemed', 'void')),
  reserved_order_id UUID REFERENCES public.orders(id) ON DELETE SET NULL,
  redeemed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT referral_reward_event_once_per_customer UNIQUE (referred_customer_id, reward_type, qualifying_order_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS referral_reward_once_per_order_type
  ON public.referral_reward_events (qualifying_order_id, reward_type);

ALTER TABLE public.referral_reward_events
  ADD COLUMN IF NOT EXISTS address_fingerprint TEXT;

UPDATE public.referral_reward_events e
SET address_fingerprint = COALESCE(
  NULLIF(e.address_fingerprint, ''),
  (
    SELECT encode(digest(
      lower(trim(coalesce(a.house_flat, ''))) || '|' ||
      lower(trim(coalesce(a.area, ''))) || '|' ||
      lower(trim(coalesce(a.city, ''))) || '|' ||
      regexp_replace(coalesce(a.pincode, ''), '[^0-9]', '', 'g'),
      'sha256'
    ), 'hex')
    FROM public.addresses a WHERE a.id = e.address_id
  ),
  encode(digest('legacy-order:' || e.qualifying_order_id::text, 'sha256'), 'hex')
)
WHERE e.address_fingerprint IS NULL OR e.address_fingerprint = '';

ALTER TABLE public.referral_reward_events
  ALTER COLUMN address_fingerprint SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS referral_reward_once_per_address
  ON public.referral_reward_events (referrer_id, address_fingerprint, reward_type);


CREATE INDEX IF NOT EXISTS referral_rewards_available_idx
  ON public.referral_reward_events (referrer_id, reward_status, created_at);

ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS referral_reward_id UUID REFERENCES public.referral_reward_events(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS referral_discount_amount NUMERIC(10,2) NOT NULL DEFAULT 0
    CHECK (referral_discount_amount >= 0);

COMMENT ON COLUMN public.orders.referral_reward_id IS
  'Referral reward consumed by this order; set only by the authenticated server workflow.';
COMMENT ON COLUMN public.orders.referral_discount_amount IS
  'Server-calculated referral discount snapshot in INR.';

ALTER TABLE public.referral_reward_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS referral_reward_events_select_own ON public.referral_reward_events;
CREATE POLICY referral_reward_events_select_own ON public.referral_reward_events
  FOR SELECT TO authenticated
  USING (referrer_id = auth.uid() OR referred_customer_id = auth.uid());

-- Applying a code is allowed only before the customer has placed any order.
-- This prevents changing referral ownership after a reward becomes foreseeable.
CREATE OR REPLACE FUNCTION public.apply_referral_code(p_code TEXT)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  actor UUID := auth.uid();
  referrer UUID;
  current_referrer UUID;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF upper(trim(coalesce(p_code, ''))) !~ '^AT-[A-F0-9]{6}$' THEN
    RAISE EXCEPTION 'Enter a valid AuroTap referral code' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO referrer
  FROM public.profiles
  WHERE referral_code = upper(trim(p_code))
    AND id <> actor
    AND role = 'customer'
    AND is_active = true
    AND deleted_at IS NULL;

  IF referrer IS NULL THEN
    RAISE EXCEPTION 'Referral code is invalid or unavailable' USING ERRCODE = '22023';
  END IF;

  SELECT referred_by INTO current_referrer
  FROM public.profiles
  WHERE id = actor AND role = 'customer' AND is_active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active customer account required' USING ERRCODE = '42501';
  END IF;
  IF current_referrer IS NOT NULL THEN
    IF current_referrer = referrer THEN RETURN referrer; END IF;
    RAISE EXCEPTION 'A referral code has already been applied to this account' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.orders WHERE customer_id = actor) THEN
    RAISE EXCEPTION 'Referral codes must be applied before your first booking' USING ERRCODE = '22023';
  END IF;

  UPDATE public.profiles SET referred_by = referrer, updated_at = now() WHERE id = actor;
  RETURN referrer;
END;
$$;

REVOKE ALL ON FUNCTION public.apply_referral_code(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.apply_referral_code(TEXT) TO authenticated;

-- A successful referral is earned only after a referred customer's first
-- completed AND paid booking. A distinct saved address is required per referral.
-- Each valid referral gives the referrer a 25% reward; every fifth distinct
-- qualified referral also grants one standard (not chilled/subscription) water can.
CREATE OR REPLACE FUNCTION public.award_referral_reward_after_order()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  referrer UUID;
  first_qualifying_order UUID;
  qualifying_address UUID;
  qualifying_fingerprint TEXT;
  qualified_count INTEGER;
  reward_kind TEXT;
BEGIN
  IF NEW.status <> 'COMPLETED'
     OR lower(coalesce(NEW.payment_status, '')) <> 'paid'
     OR (TG_OP = 'UPDATE' AND OLD.status = 'COMPLETED' AND lower(coalesce(OLD.payment_status, '')) = 'paid') THEN
    RETURN NEW;
  END IF;

  SELECT p.referred_by INTO referrer
  FROM public.profiles p
  WHERE p.id = NEW.customer_id
    AND p.referred_by IS NOT NULL
    AND p.role = 'customer'
    AND p.is_active = true;

  IF referrer IS NULL THEN RETURN NEW; END IF;

  -- Only the first qualifying order of a referred customer counts.
  SELECT o.id, o.address_id INTO first_qualifying_order, qualifying_address
  FROM public.orders o
  WHERE o.customer_id = NEW.customer_id
    AND o.status = 'COMPLETED'
    AND lower(coalesce(o.payment_status, '')) = 'paid'
  ORDER BY o.created_at ASC, o.id ASC
  LIMIT 1;

  IF first_qualifying_order IS DISTINCT FROM NEW.id THEN RETURN NEW; END IF;
  IF qualifying_address IS NULL THEN RETURN NEW; END IF;

  SELECT encode(digest(
    lower(trim(coalesce(a.house_flat, ''))) || '|' ||
    lower(trim(coalesce(a.area, ''))) || '|' ||
    lower(trim(coalesce(a.city, ''))) || '|' ||
    regexp_replace(coalesce(a.pincode, ''), '[^0-9]', '', 'g'),
    'sha256'
  ), 'hex')
  INTO qualifying_fingerprint
  FROM public.addresses a WHERE a.id = qualifying_address;
  IF qualifying_fingerprint IS NULL THEN RETURN NEW; END IF;

  -- Serialize qualification per referrer and enforce one referral per normalized
  -- physical address, even if a customer later deletes their saved address.
  PERFORM pg_advisory_xact_lock(hashtext(referrer::text));

  IF EXISTS (
    SELECT 1 FROM public.referral_reward_events e
    WHERE e.referrer_id = referrer
      AND e.referred_customer_id = NEW.customer_id
      AND e.reward_type = 'discount_25'
  ) THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM public.referral_reward_events e
    WHERE e.referrer_id = referrer
      AND e.address_fingerprint = qualifying_fingerprint
      AND e.reward_type = 'discount_25'
  ) THEN RETURN NEW; END IF;

  SELECT COUNT(DISTINCT e.referred_customer_id)::INTEGER INTO qualified_count
  FROM public.referral_reward_events e
  WHERE e.referrer_id = referrer AND e.reward_type = 'discount_25';

  INSERT INTO public.referral_reward_events (
    referrer_id, referred_customer_id, qualifying_order_id, address_id, address_fingerprint, reward_type
  ) VALUES (
    referrer, NEW.customer_id, NEW.id, qualifying_address, qualifying_fingerprint, 'discount_25'
  ) ON CONFLICT (qualifying_order_id, reward_type) DO NOTHING;

  -- Count only distinct-address, successfully paid referral events.
  SELECT COUNT(DISTINCT e.referred_customer_id)::INTEGER INTO qualified_count
  FROM public.referral_reward_events e
  WHERE e.referrer_id = referrer AND e.reward_type = 'discount_25';

  IF qualified_count > 0 AND qualified_count % 5 = 0 THEN
    reward_kind := 'free_water_can';
    IF NOT EXISTS (
      SELECT 1 FROM public.referral_reward_events e
      WHERE e.referrer_id = referrer
        AND e.reward_type = reward_kind
        AND e.qualifying_order_id = NEW.id
    ) THEN
      INSERT INTO public.referral_reward_events (
        referrer_id, referred_customer_id, qualifying_order_id, address_id, address_fingerprint, reward_type
      ) VALUES (
        referrer, NEW.customer_id, NEW.id, qualifying_address, qualifying_fingerprint, reward_kind
      ) ON CONFLICT DO NOTHING;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS orders_award_referral_reward ON public.orders;
CREATE TRIGGER orders_award_referral_reward
  AFTER INSERT OR UPDATE OF status, payment_status ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.award_referral_reward_after_order();

-- Never let customers create or alter reward ledger entries directly.
REVOKE INSERT, UPDATE, DELETE ON public.referral_reward_events FROM anon, authenticated;
GRANT SELECT ON public.referral_reward_events TO authenticated;


-- Reward lifecycle follows the linked order: cancellation releases the reward;
-- completion consumes it. A pending booking cannot be used to reuse rewards.
CREATE OR REPLACE FUNCTION public.sync_referral_reward_order_state()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.referral_reward_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.status = 'CANCELLED' THEN
    UPDATE public.referral_reward_events
    SET reward_status = 'available', reserved_order_id = NULL
    WHERE id = NEW.referral_reward_id AND reward_status = 'reserved'
      AND (reserved_order_id = NEW.id OR reserved_order_id IS NULL);
  ELSIF NEW.status = 'COMPLETED' AND lower(coalesce(NEW.payment_status, '')) = 'paid' THEN
    UPDATE public.referral_reward_events
    SET reward_status = 'redeemed', reserved_order_id = NEW.id, redeemed_at = COALESCE(redeemed_at, now())
    WHERE id = NEW.referral_reward_id AND reward_status = 'reserved'
      AND (reserved_order_id = NEW.id OR reserved_order_id IS NULL);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS orders_sync_referral_reward ON public.orders;
CREATE TRIGGER orders_sync_referral_reward
  AFTER UPDATE OF status, payment_status ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.sync_referral_reward_order_state();

-- Preserve the approved ₹20 supplier entitlement when AuroTap funds a discount.
CREATE OR REPLACE FUNCTION public.complete_supplier_order_atomic(
  p_order_id UUID,
  p_supplier_id UUID,
  p_payment_confirmed BOOLEAN,
  p_payment_reference TEXT,
  p_payment_collector TEXT
)
RETURNS SETOF public.orders
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role TEXT;
  v_order public.orders%ROWTYPE;
  v_now TIMESTAMPTZ := NOW();
  v_was_paid BOOLEAN;
  v_method TEXT;
  v_supplier_entitlement NUMERIC(10,2);
BEGIN
  IF auth.uid() IS DISTINCT FROM p_supplier_id THEN
    RAISE EXCEPTION 'supplier_identity_mismatch' USING ERRCODE = '42501';
  END IF;
  SELECT p.role INTO v_role FROM public.profiles p WHERE p.id = auth.uid();
  IF v_role IS DISTINCT FROM 'supplier' THEN RAISE EXCEPTION 'supplier_role_required' USING ERRCODE = '42501'; END IF;

  SELECT o.* INTO v_order FROM public.orders o
  WHERE o.id = p_order_id AND o.supplier_id = p_supplier_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found_or_forbidden' USING ERRCODE = '42501'; END IF;
  IF upper(COALESCE(v_order.status, '')) <> 'IN_PROGRESS' THEN
    RAISE EXCEPTION 'invalid_order_transition' USING ERRCODE = '40001';
  END IF;

  v_was_paid := lower(COALESCE(v_order.payment_status, 'unpaid')) = 'paid';
  v_method := lower(COALESCE(v_order.payment_method, 'cash'));
  IF NOT v_was_paid AND p_payment_confirmed IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'payment_confirmation_required' USING ERRCODE = '22023';
  END IF;
  IF NOT v_was_paid AND v_method = 'upi' AND NULLIF(btrim(COALESCE(p_payment_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'upi_reference_required' USING ERRCODE = '22023';
  END IF;
  IF NOT v_was_paid AND (p_payment_collector IS NULL OR p_payment_collector NOT IN ('supplier', 'aurotap')) THEN
    RAISE EXCEPTION 'payment_collector_required' USING ERRCODE = '22023';
  END IF;

  v_supplier_entitlement := NULL;
  IF lower(COALESCE(v_order.service_type, '')) = 'water_can'
     AND COALESCE(v_order.can_count, 0) = 1
     AND round(COALESCE(v_order.base_amount, 0) + COALESCE(v_order.referral_discount_amount, 0), 2) = 20 THEN
    v_supplier_entitlement := 20;
  END IF;

  UPDATE public.orders
  SET status = 'COMPLETED',
      completed_at = v_now,
      payment_status = CASE WHEN v_was_paid THEN payment_status ELSE 'paid' END,
      payment_confirmed_at = CASE WHEN v_was_paid THEN payment_confirmed_at ELSE v_now END,
      payment_reference = CASE WHEN v_was_paid THEN payment_reference ELSE NULLIF(btrim(COALESCE(p_payment_reference, '')), '') END,
      payment_collector = CASE WHEN v_was_paid THEN payment_collector ELSE p_payment_collector END,
      payment_collected_by = CASE WHEN v_was_paid THEN payment_collected_by WHEN p_payment_collector = 'supplier' THEN p_supplier_id ELSE NULL END,
      payment_collected_amount = CASE WHEN v_was_paid THEN payment_collected_amount ELSE total_amount END,
      payment_collected_at = CASE WHEN v_was_paid THEN payment_collected_at ELSE v_now END,
      supplier_payout = CASE WHEN v_supplier_entitlement IS NOT NULL AND financials_posted_at IS NULL
          AND COALESCE(supplier_payout, 0) <> v_supplier_entitlement THEN v_supplier_entitlement ELSE supplier_payout END,
      payout_status = CASE WHEN v_supplier_entitlement IS NOT NULL AND financials_posted_at IS NULL
          AND COALESCE(supplier_payout, 0) <> v_supplier_entitlement THEN 'pending' ELSE payout_status END
  WHERE id = p_order_id AND supplier_id = p_supplier_id RETURNING * INTO v_order;

  IF v_supplier_entitlement IS NOT NULL AND v_order.financials_posted_at IS NULL THEN
    IF EXISTS (SELECT 1 FROM public.wallet_ledger wl WHERE wl.order_id = p_order_id AND wl.entry_type = 'ORDER_EARNING') THEN
      RAISE EXCEPTION 'order_earning_ledger_already_exists' USING ERRCODE = '23505';
    END IF;
    INSERT INTO public.wallet_ledger (
      payee_id, payee_role, order_id, entry_type, amount, note, metadata, created_by
    ) VALUES (
      p_supplier_id, 'supplier', p_order_id, 'ORDER_EARNING', v_supplier_entitlement,
      'Supplier entitlement for verified single-can water order; referral discount funded by AuroTap',
      jsonb_build_object('service_type','water_can','can_count',1,
        'customer_total',v_order.total_amount,
        'referral_discount_amount',COALESCE(v_order.referral_discount_amount,0),
        'gross_can_value',COALESCE(v_order.base_amount,0)+COALESCE(v_order.referral_discount_amount,0)),
      p_supplier_id
    );
    UPDATE public.orders SET financials_posted_at = v_now, financials_payee_id = p_supplier_id
    WHERE id = p_order_id AND supplier_id = p_supplier_id RETURNING * INTO v_order;
  END IF;
  RETURN NEXT v_order;
END;
$$;

REVOKE ALL ON FUNCTION public.complete_supplier_order_atomic(UUID, UUID, BOOLEAN, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.complete_supplier_order_atomic(UUID, UUID, BOOLEAN, TEXT, TEXT) TO authenticated;


-- Prevent direct PostgREST profile updates from changing referral attribution,
-- tiers, or credit balances after the authenticated API's validation.
CREATE OR REPLACE FUNCTION public.guard_profile_referral_fields()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND auth.uid() = OLD.id AND OLD.role <> 'admin' THEN
    IF NEW.referral_credits IS DISTINCT FROM OLD.referral_credits OR NEW.tier IS DISTINCT FROM OLD.tier THEN
      RAISE EXCEPTION 'Referral balances and tiers are system-managed' USING ERRCODE = '42501';
    END IF;
    IF NEW.referred_by IS DISTINCT FROM OLD.referred_by THEN
      IF OLD.referred_by IS NOT NULL OR NEW.referred_by IS NULL OR NEW.referred_by = OLD.id THEN
        RAISE EXCEPTION 'Referral attribution can only be set once' USING ERRCODE = '42501';
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM public.profiles p
        WHERE p.id = NEW.referred_by AND p.role = 'customer'
          AND p.is_active = true AND p.deleted_at IS NULL
      ) OR EXISTS (SELECT 1 FROM public.orders o WHERE o.customer_id = OLD.id) THEN
        RAISE EXCEPTION 'Referral attribution is invalid or the account already has orders' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS profiles_guard_referral_fields ON public.profiles;
CREATE TRIGGER profiles_guard_referral_fields
  BEFORE UPDATE OF referred_by, referral_credits, tier ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.guard_profile_referral_fields();

-- Referral reward amounts are accepted only from the authenticated server API.
-- Browser clients cannot forge a discount by inserting/updating orders directly.
CREATE OR REPLACE FUNCTION public.guard_order_referral_fields()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF auth.uid() IS NOT NULL
     AND auth.uid() = COALESCE(NEW.customer_id, OLD.customer_id) THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.referral_reward_id IS NOT NULL OR COALESCE(NEW.referral_discount_amount, 0) <> 0 THEN
        RAISE EXCEPTION 'Referral discounts must be applied through checkout' USING ERRCODE = '42501';
      END IF;
    ELSIF NEW.referral_reward_id IS DISTINCT FROM OLD.referral_reward_id
       OR NEW.referral_discount_amount IS DISTINCT FROM OLD.referral_discount_amount THEN
      RAISE EXCEPTION 'Referral reward details are immutable' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS orders_guard_referral_fields ON public.orders;
CREATE TRIGGER orders_guard_referral_fields
  BEFORE INSERT OR UPDATE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.guard_order_referral_fields();

COMMIT;


-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/029_ncr_coming_soon_zones.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroTap NCR expansion staging: add non-bookable catch-all zones.
-- Safe to run repeatedly. This does NOT activate NCR bookings.
-- Existing slugs are left untouched so manually managed zone settings are not overwritten.
-- Apply only after reviewing the target Supabase schema; this repository's runtime already
-- expects these columns, but the service_zones DDL is managed outside the checked-in migrations.

BEGIN;

DO $preflight$
DECLARE
  required_column TEXT;
BEGIN
  IF to_regclass('public.service_zones') IS NULL THEN
    RAISE EXCEPTION 'public.service_zones is missing; stop and verify the deployed Supabase schema before applying this seed';
  END IF;

  FOREACH required_column IN ARRAY ARRAY[
    'city', 'name', 'slug', 'status', 'pincodes',
    'center_lat', 'center_lng', 'radius_km', 'services',
    'is_catch_all', 'notes'
  ]
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM information_schema.columns
      WHERE table_schema = 'public'
        AND table_name = 'service_zones'
        AND column_name = required_column
    ) THEN
      RAISE EXCEPTION 'public.service_zones.% is missing; stop and verify the deployed Supabase schema', required_column;
    END IF;
  END LOOP;
END
$preflight$;

INSERT INTO public.service_zones
  (city, name, slug, status, pincodes, center_lat, center_lng, radius_km, services, is_catch_all, notes)
VALUES
  ('Delhi', 'Delhi NCR — Delhi', 'delhi-delhi-ncr-delhi', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only. All localities are non-bookable until service capacity and pincode coverage are verified.'),
  ('New Delhi', 'Delhi NCR — New Delhi', 'new-delhi-delhi-ncr-new-delhi', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only. All localities are non-bookable until service capacity and pincode coverage are verified.'),
  ('Noida', 'Delhi NCR — Noida', 'noida-delhi-ncr-noida', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only; includes sectors as waitlist interest, not confirmed service coverage.'),
  ('Greater Noida', 'Delhi NCR — Greater Noida', 'greater-noida-delhi-ncr-greater-noida', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only; includes sectors as waitlist interest, not confirmed service coverage.'),
  ('Gautam Buddha Nagar', 'Delhi NCR — Gautam Buddha Nagar', 'gautam-buddha-nagar-delhi-ncr-gautam-buddha-nagar', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only. District/city aliases are staged as non-bookable.'),
  ('Ghaziabad', 'Delhi NCR — Ghaziabad', 'ghaziabad-delhi-ncr-ghaziabad', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only; all localities remain non-bookable until service capacity and pincode coverage are verified.'),
  ('Gurugram', 'Delhi NCR — Gurugram', 'gurugram-delhi-ncr-gurugram', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only; all localities remain non-bookable until service capacity and pincode coverage are verified.'),
  ('Gurgaon', 'Delhi NCR — Gurgaon', 'gurgaon-delhi-ncr-gurgaon', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'City-name alias for Gurugram; expansion interest only and non-bookable.'),
  ('Faridabad', 'Delhi NCR — Faridabad', 'faridabad-delhi-ncr-faridabad', 'COMING_SOON', ARRAY[]::text[], NULL, NULL, NULL, NULL, TRUE,
   'Expansion interest only; all localities remain non-bookable until service capacity and pincode coverage are verified.')
ON CONFLICT (slug) DO NOTHING;

-- Post-apply verification: all expected labels should exist. This does not change existing rows.
DO $verify$
DECLARE
  expected_count INTEGER := 9;
  actual_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO actual_count
  FROM public.service_zones
  WHERE slug IN (
    'delhi-delhi-ncr-delhi',
    'new-delhi-delhi-ncr-new-delhi',
    'noida-delhi-ncr-noida',
    'greater-noida-delhi-ncr-greater-noida',
    'gautam-buddha-nagar-delhi-ncr-gautam-buddha-nagar',
    'ghaziabad-delhi-ncr-ghaziabad',
    'gurugram-delhi-ncr-gurugram',
    'gurgaon-delhi-ncr-gurgaon',
    'faridabad-delhi-ncr-faridabad'
  );

  IF actual_count <> expected_count THEN
    RAISE EXCEPTION 'NCR zone seed verification failed: expected % rows, found %', expected_count, actual_count;
  END IF;
END
$verify$;

COMMIT;

